package com.aistock.prediction.portfolioquestion;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import org.flywaydb.core.Flyway;import java.util.*;import java.time.*;import static com.aistock.prediction.portfolioquestion.QuestionEvidence.*;
@Tag("mysql") class PortfolioQuestionMigrationTest {
 @Test void upgradingV10PreservesValuationsPredictionsAndComparisons(){String url=System.getenv("PREDICTION_TEST_DB_URL"),secret=System.getenv("PREDICTION_TEST_DB_PASSWORD");if(!"jdbc:mysql://127.0.0.1:13316/stock_prediction_test?serverTimezone=UTC".equals(url)||secret==null||secret.isBlank())throw new IllegalStateException("Only isolated test schema allowed");var ds=new DriverManagerDataSource(url,"root",secret);var jdbc=new JdbcTemplate(ds);assertEquals("stock_prediction_test",jdbc.queryForObject("select database()",String.class));var old=Flyway.configure().dataSource(ds).locations("classpath:db/migration").target("10").cleanDisabled(false).load();old.clean();old.migrate();var now=java.sql.Timestamp.from(Instant.parse("2026-10-20T00:00:00Z"));var prediction=UUID.randomUUID();var comparison=UUID.randomUUID();jdbc.update("insert into portfolio_analysis_result(analysis_id,owner_id,snapshot_json,quotes_json,result_json,source_hash,created_at) values(?,?,'{}','{}',?,?,?)",ID.toString(),OWNER.toString(),saved().toString(),"a".repeat(64),now);jdbc.update("insert into stock_comparison_result(comparison_id,owner_id,result_json,summary_json,source_snapshots_json,source_hash,created_at) values(?,?,'{\"migrationSentinel\":true}','{}','[]',?,?)",comparison.toString(),OWNER.toString(),"b".repeat(64),now);jdbc.update("insert into forecast_request(prediction_id,user_id,operation_id,request_hash,model_id,instrument_id,horizon,state,model_json,snapshot_json,created_at,expires_at) values(?,?,?,?,?,'SH600030',5,'SUCCEEDED','{}','{\"migrationSentinel\":true}',?,?)",prediction.toString(),OWNER.toString(),UUID.randomUUID().toString(),"c".repeat(64),UUID.randomUUID().toString(),now,java.sql.Timestamp.from(now.toInstant().plusSeconds(60)));String before=jdbc.queryForObject("select result_json from portfolio_analysis_result where analysis_id=?",String.class,ID.toString());var latest=Flyway.configure().dataSource(ds).locations("classpath:db/migration").target("11").load();assertEquals(1,latest.migrate().migrationsExecuted);assertEquals(0,latest.migrate().migrationsExecuted);assertEquals(before,jdbc.queryForObject("select result_json from portfolio_analysis_result where analysis_id=?",String.class,ID.toString()));assertEquals(1,jdbc.queryForObject("select count(*) from forecast_request where prediction_id=?",Integer.class,prediction.toString()));assertEquals(1,jdbc.queryForObject("select count(*) from stock_comparison_result where comparison_id=?",Integer.class,comparison.toString()));assertEquals("11",jdbc.queryForObject("select version from flyway_schema_history where success=1 order by installed_rank desc limit 1",String.class));}
}
